# IncidentReportHR: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Incidentreporthr:
    report_id: str = None  # ID
    reported_at: str = None  # ISO 8601
    category: str = None  # safety/conduct/other
    status: str = None  # open/investigating/closed
    reporter: str = None  # Reporter (may be anonymous)

REQUIRED = ["report_id", "reported_at", "category", "status"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'report_id': 'HR-INC-2201', 'reported_at': '2026-05-11T15:00:00Z', 'category': 'safety', 'status': 'closed', 'reporter': 'anonymous'}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))
